mapper.codeEditorJavascript:
// pos-invoice - Positionen aufbereiten.
// Input:  positionen  = 12.parsedResult.positions (Extraktion aus dem Beleg)
//         voucherDate = roher Lexware-Zeitstempel mit Zeitzone
// Output: alle[] {pos, nr, stueck, kg, netto} + anzahl + datum + summe + fehlertext
//         + notiz   -> stille Skips, nur fuers Make-Log
//         + warnung -> echte Datenluecken, gehen nach ⚙ Hinweis
//
// Reihenfolge ist bewusst: Lueckenlos-Pruefung laeuft VOR dem Filtern der
// Zeilen ohne Artikelnummer, sonst bricht sie an der uebersprungenen Zeile.
//
// Die Abstimmung Positionssumme <-> Belegbetrag findet hier NICHT statt.
// Der Lexware-MCP liefert sie fertig als checksum.positionSumReconciled /
// checksum.matches und wertet dabei amountBasis aus. Eine Zweitimplementierung
// haette diese Unterscheidung nicht und wuerde Belege der alten Druckvorlage
// (Zeilenbetraege netto) gegen den Bruttobetrag pruefen - dauerhaft falsch.
// Die Checksum haengt stattdessen als Filterbedingung vor diesem Modul.

var arr = function (v) {
  if (Array.isArray(v)) return v;
  if (typeof v === "string" && v.trim()) {
    try { var p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
  }
  return [];
};

var fehler = [];
var hinweise = [];   // stille Skips - erwartetes Normalverhalten
var warnungen = [];  // Hilfsannahmen, die ein Ergebnis unsicher machen

// Datum als reiner YYYY-MM-DD-String. formatDate() wuerde den Zeitstempel als
// UTC lesen und bei +02:00 den Vortag liefern - genau der Fallstrick, der die
// Preis-Aufloesung am Stichtag auf die falsche Version schickt.
var datum = String(input.voucherDate == null ? "" : input.voucherDate).slice(0, 10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(datum)) fehler.push("Leistungsdatum unlesbar: " + input.voucherDate);

var roh = arr(input.positionen);
if (roh.length === 0) fehler.push("keine Positionen extrahiert");

var sortiert = roh.slice().sort(function (a, b) { return Number(a.pos) - Number(b.pos); });
sortiert.forEach(function (p, i) {
  if (Number(p.pos) !== i + 1)
    fehler.push("Position " + p.pos + " an Stelle " + (i + 1) + " - Zeile fehlt oder Reihenfolge gestoert");
});

var alle = [];
var summe = 0;
sortiert.forEach(function (p) {
  var nr = String(p.articleNumber == null ? "" : p.articleNumber).trim();
  // Zeilen ohne Artikelnummer (z.B. "Abholung vor Ort") sind ein STILLER Skip:
  // kein Fehler und keine Warnung, denn sie tragen keine Ware und haben kein
  // Produkt in der Base. Sie duerfen ⚙ Hinweis nicht belegen, sonst geht das
  // echte Problem im Rauschen unter.
  if (!nr) {
    hinweise.push("Pos " + p.pos + " (" + String(p.name == null ? "" : p.name) + ") ohne Artikelnummer - uebersprungen");
    return;
  }
  var stueck = Number(p.quantity);
  if (!isFinite(stueck)) { fehler.push("Pos " + p.pos + " (" + nr + "): Menge fehlt"); return; }

  // Nettobetrag der Zeile IMMER aus lineAmountNet. Der MCP stellt das Feld
  // vorlagenunabhaengig bereit; lineAmount ist bei der neuen Belegvorlage
  // brutto und darf nicht in ein Nettofeld. Kein Umrechnen, kein Steuersatz.
  var netto = Number(p.lineAmountNet);
  if (!isFinite(netto)) { fehler.push("Pos " + p.pos + " (" + nr + "): Nettobetrag fehlt in der Extraktion"); return; }
  netto = Math.round(netto * 100) / 100;

  // Rechnungen fuehren keine Gewichtsspalte; die Grammatur steckt in der
  // Artikelbezeichnung und kommt als gramsPerUnit aus der Extraktion.
  var gramm = Number(p.gramsPerUnit);
  if ((!isFinite(gramm) || gramm <= 0) && stueck > 0) {
    var g = Number(p.grams);
    if (isFinite(g) && g > 0) {
      gramm = g / stueck;
      // Das ist eine Hilfsannahme: die kg-Ableitung steht danach auf einer
      // Division statt auf einem gelesenen Wert -> sichtbar machen.
      warnungen.push("Pos " + p.pos + " (" + nr + "): gramsPerUnit fehlt, aus grams abgeleitet = " + gramm + " g");
    }
  }
  if (!isFinite(gramm) || gramm <= 0) { fehler.push("Pos " + p.pos + " (" + nr + "): Grammatur nicht ermittelbar"); return; }

  summe += netto;
  alle.push({ pos: Number(p.pos), nr: nr, stueck: stueck, kg: Math.round(stueck * gramm) / 1000, netto: netto });
});

if (alle.length === 0 && fehler.length === 0) fehler.push("keine buchbaren Positionen nach Filterung");

return {
  ok: fehler.length === 0,
  datum: datum,
  alle: alle,
  anzahl: alle.length,
  summe: Math.round(summe * 100) / 100,
  fehlertext: fehler.join(" \u00b7 "),
  notiz: hinweise.join(" \u00b7 "),
  warnung: warnungen.join(" \u00b7 ")
};

// Verdikt + fertiger Hinweistext fuer Umsaetze."⚙ Hinweis".
// Kaskade: Netto-Rekonstruktion -> Parser-Fehler -> Aufloesungs-Luecke -> Warnungen.
// Laeuft IMMER (auch bei 0 aufgeloesten Zeilen), damit der Hinweis geschrieben
// wird; nur der nachgelagerte Schreib-Iterator haengt an ok.
//
// Stille Skips (73.result.notiz) landen hier BEWUSST nicht: ⚙ Hinweis ist ein
// Waechterfeld, kein Protokoll. Steht dort Text, soll das etwas bedeuten.

var arr = function (v) {
  if (Array.isArray(v)) return v;
  if (typeof v === "string" && v.trim()) {
    try { var p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
  }
  return [];
};
var truthy = function (v) { return v === true || v === "true"; };
var fmt = function (v) { var n = Number(v); return isFinite(n) ? n.toFixed(2) : "?"; };

var gemappt = arr(input.aufgeloest);
var erwartet = Number(input.erwartet) || 0;
var teile = [];
var parserOk = truthy(input.parser_ok);
var ok = parserOk;

// Netto zuerst - das ist die teuerste Fehlerart.
// Umsaetze.Nettoumsatz ist ein Rollup ueber die Positionsnettos, und
// Provision = Nettoumsatz x Satz. Trifft die Summe der rekonstruierten
// lineAmountNet das gedruckte Gesamt-Netto nicht, ist JEDE einzelne Zeile
// unsicher - dann lieber gar keine Positionen als plausibel aussehende
// falsche. netReconciled kann null sein (keine Nettofelder ableitbar),
// deshalb !== true statt === false.
if (!truthy(input.net_ok)) {
  ok = false;
  teile.push("Nettosumme nicht rekonstruierbar: Positionen " + fmt(input.pos_netto) +
             " EUR vs. Beleg " + fmt(input.pdf_netto) +
             " EUR - keine Positionen geschrieben");
}

if (!parserOk && input.fehlertext) teile.push(String(input.fehlertext));

if (parserOk && gemappt.length !== erwartet) {
  ok = false;
  var da = {};
  gemappt.forEach(function (r) { da[String(Number(r.pos))] = true; });
  var fehlend = arr(input.alle)
    .map(function (p) { return Number(p.pos); })
    .filter(function (p) { return !da[String(p)]; });
  teile.push("Nicht aufloesbar (Produkt/Preis/Bestand fehlt): Pos " +
             (fehlend.length ? fehlend.join(", ") : "unbekannt"));
}

if (input.warnung) teile.push(String(input.warnung));

return { ok: ok, anzahl: gemappt.length, hinweis: teile.join(" \u00b7 ") };

// pos-invoice - Bestandspruefung zur Rechnung zuordnen.
//
// Input:  rechnung      = 12.parsedResult.positions
//         pruefungen    = 111.data.records  (Bestandspruefungen des Stores, ohne Ungueltig)
//         bspPositionen = 112.data.records  (Positionen aller BP des Stores)
//         belege        = 113.data.records  (Belege vom Typ Bestandsprotokoll)
//         rgNummer      = 6.body.voucherNumber
//         belegdatum    = YYYY-MM-DD des Belegs
//
// Alle drei REST-Reads laufen mit cellFormat=string. Link-Felder kommen dadurch
// als Primaerwert im Klartext ("10001-002", "BSP-10009-2026-08-03", "RG-10113-1")
// statt als Record-ID. Genau deshalb braucht die Zuordnung KEINE Lookup-Felder
// in Airtable - Belege traegt Bestandspruefung und Umsatz nebeneinander, und
// beide sind hier als Name lesbar.
//
// Zugeordnet wird ueber die Positionen, nicht ueber das Datum: die Menge auf der
// Rechnung ist exakt die positive Differenz (SOLL - IST) der Bestandspruefung.
// Das Datum aus der PDF-Zeile "geprueft am" ist nachweislich unzuverlaessig und
// wird bewusst nicht ausgewertet.
//
// Output: verdikt "treffer" | "unklar" | "uebersprungen"

var F = {
  BSP_ID:     "fld24GCd9UoMFtIW6",
  BSP_STATUS: "fldVx19XWUNiag4yJ",
  POS_ID:     "fldVekCJcYqoCakJw",
  POS_PRODUKT:"fldHcHaafIcSK1XGh",
  POS_DIFF:   "fldFxKTS4YK7pI2Xr",
  BLG_ID:     "fld7DgKiRjGPJitvf",
  BLG_BSP:    "fldbzOIOSaNcwdNAL",
  BLG_UMS:    "fldI5lU4NQ7ymG4d0"
};

var SEITENGROESSE = 100;

var arr = function (v) {
  if (Array.isArray(v)) return v;
  if (typeof v === "string" && v.trim()) {
    try { var p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
  }
  return [];
};
var txt = function (v) { return String(v == null ? "" : v).trim(); };
var feld = function (rec, id) { return txt((rec && rec.fields ? rec.fields[id] : "")); };

var rgNummer   = txt(input.rgNummer);
var belegdatum = txt(input.belegdatum);

var raus = function (verdikt, hinweis, belegId, bspName) {
  return {
    verdikt:  verdikt,
    beleg_id: belegId || "",
    bsp_name: bspName || "",
    hinweis:  hinweis || ""
  };
};

// ---------------------------------------------------------------- Rechnung
// Zeilen ohne Artikelnummer ("Abholung vor Ort") tragen keine Ware und fallen
// raus - dieselbe Regel wie im Positions-Parser der Route 1.
var rgMenge = {};
var rgSkus  = [];
arr(input.rechnung).forEach(function (p) {
  var nr = txt(p.articleNumber);
  var m  = Number(p.quantity);
  if (!nr || !isFinite(m)) return;
  rgMenge[nr] = (rgMenge[nr] || 0) + m;
  if (rgSkus.indexOf(nr) === -1) rgSkus.push(nr);
});
if (rgSkus.length === 0) {
  return raus("unklar", "Keine Bestandspruefung zugeordnet: die Rechnung fuehrt keine Warenposition.");
}

// ------------------------------------------------------------------ Belege
// Ein Beleg vom Typ Bestandsprotokoll traegt die BP und - sobald vergeben -
// den Umsatz. Das ist die Vergabeliste.
var belege = arr(input.belege);
var belegZurBsp = {};
var vergebenAn  = {};
var schonAmEigenenUmsatz = "";

belege.forEach(function (b) {
  var bsp = feld(b, F.BLG_BSP);
  if (!bsp) return;
  belegZurBsp[bsp] = { id: b.id, nummer: feld(b, F.BLG_ID) };
  var ums = feld(b, F.BLG_UMS);
  if (!ums) return;
  if (ums === rgNummer) schonAmEigenenUmsatz = bsp;
  else vergebenAn[bsp] = ums;
});

// Idempotenz: laeuft die Rechnung ein zweites Mal durch (voucher.status.changed
// feuert je Statuswechsel), ist die Verknuepfung schon da. Still aussteigen -
// kein Write, keine Meldung.
if (schonAmEigenenUmsatz) {
  return raus("uebersprungen", "", "", schonAmEigenenUmsatz);
}

// Harte Kante: die Vergabeliste ist auf eine Seite begrenzt. Laeuft sie voll,
// koennte eine bereits vergebene BP unsichtbar und damit ein zweites Mal
// zugeordnet werden - das ist die einzige Richtung, in der ein falscher Link
// entstehen kann. Deshalb hier Stopp statt Rueckfall auf "sieht frei aus".
if (belege.length >= SEITENGROESSE) {
  return raus("unklar",
    "Keine Bestandspruefung zugeordnet: die Belegliste hat die Seitengrenze von "
    + SEITENGROESSE + " erreicht, eine bereits vergebene Pruefung waere hier nicht sichtbar. "
    + "Filter in Modul 113 nachruesten (Zeitfenster oder Store).");
}

// -------------------------------------------------------------- Positionen
// Gruppiert wird ueber die Positions-ID ("BSP-10009-2026-08-03 #3"), nicht ueber
// den Link - der Name steht so direkt im Text.
var gruppen = {};
var positionen = arr(input.bspPositionen);
positionen.forEach(function (p) {
  var pid = feld(p, F.POS_ID);
  var i = pid.indexOf(" #");
  if (i <= 0) return;
  var bsp = pid.slice(0, i);
  var sku = feld(p, F.POS_PRODUKT);
  if (!sku) return;
  var diff = Number(feld(p, F.POS_DIFF));
  if (!isFinite(diff)) diff = 0;
  if (!gruppen[bsp]) gruppen[bsp] = {};
  gruppen[bsp][sku] = (gruppen[bsp][sku] || 0) + Math.max(diff, 0);
});

var positionenAmLimit = positionen.length >= SEITENGROESSE;

// --------------------------------------------------------------- Kandidaten
var gueltig = [];
var protokoll = [];

arr(input.pruefungen).forEach(function (bp) {
  var name = feld(bp, F.BSP_ID);
  if (!name) return;

  if (vergebenAn[name]) {
    protokoll.push(name + " (bereits an " + vergebenAn[name] + " vergeben)");
    return;
  }
  var beleg = belegZurBsp[name];
  if (!beleg) {
    protokoll.push(name + " (kein Beleg vorhanden)");
    return;
  }
  var gruppe = gruppen[name];
  if (!gruppe) {
    protokoll.push(name + " (keine Positionen gefunden)");
    return;
  }

  var treffer = 0;
  var widerspruch = [];
  var luecke = [];

  rgSkus.forEach(function (sku) {
    if (Object.prototype.hasOwnProperty.call(gruppe, sku)) {
      if (gruppe[sku] === rgMenge[sku]) treffer++;
      else widerspruch.push(sku + " Rechnung " + rgMenge[sku] + " / Pruefung " + gruppe[sku]);
    } else {
      // Nicht gebuchte Position: in der Pruefung existiert die Zeile gar nicht.
      // Das ist die Signatur einer teilgebuchten Pruefung und disqualifiziert
      // nicht - ein Mengenwiderspruch schon.
      luecke.push(sku);
    }
  });

  Object.keys(gruppe).forEach(function (sku) {
    if (gruppe[sku] > 0 && rgSkus.indexOf(sku) === -1)
      widerspruch.push(sku + " Pruefung " + gruppe[sku] + " fehlt auf der Rechnung");
  });

  var eintrag = {
    name: name,
    belegId: beleg.id,
    belegNummer: beleg.nummer,
    treffer: treffer,
    luecke: luecke,
    widerspruch: widerspruch,
    status: feld(bp, F.BSP_STATUS)
  };

  // Untergrenze: ohne sie passt eine Rechnung aus lauter Luecken auf jede
  // beliebige Pruefung.
  if (widerspruch.length === 0 && treffer >= 2 && treffer > rgSkus.length / 2) {
    gueltig.push(eintrag);
  } else if (widerspruch.length > 0) {
    protokoll.push(name + " (" + widerspruch.length + " Widerspruch"
      + (widerspruch.length === 1 ? "" : "e") + ": " + widerspruch.join(", ") + ")");
  } else {
    protokoll.push(name + " (nur " + treffer + " von " + rgSkus.length + " Positionen belegt)");
  }
});

// ------------------------------------------------------------------ Verdikt
if (gueltig.length === 1) {
  var t = gueltig[0];
  var zeilen = [];
  if (t.luecke.length)
    zeilen.push("Nicht gebucht in der Pruefung, auf der Rechnung gefuehrt: " + t.luecke.join(", "));
  if (t.status && t.status !== "Abgeschlossen")
    zeilen.push("Pruefung hat Status " + t.status + ".");
  if (positionenAmLimit)
    zeilen.push("Positionsliste am Seitenlimit (" + SEITENGROESSE + ") - Filter in Modul 112 pruefen.");
  // Das Pruefdatum steckt als Text in der BSP-ID, es muss nicht geparst werden.
  var pruefdatum = t.name.slice(-10);
  if (belegdatum && /^\d{4}-\d{2}-\d{2}$/.test(pruefdatum) && pruefdatum !== belegdatum)
    zeilen.push("Belegdatum " + belegdatum + " weicht vom Pruefdatum " + pruefdatum + " ab.");

  var kopf = "Bestandspruefung " + t.name + " ueber Beleg " + t.belegNummer
           + " verknuepft (" + t.treffer + " von " + rgSkus.length + " Positionen exakt).";

  return raus("treffer", zeilen.length ? kopf + "\n" + zeilen.join("\n") : "", t.belegId, t.name);
}

var grund = gueltig.length > 1
  ? "mehrere passende Pruefungen (" + gueltig.map(function (g) { return g.name; }).join(", ") + ")"
  : "keine eindeutige Pruefung";

var meldung = ["Bestandspruefung nicht verknuepft - " + grund + "."];
if (rgSkus.length < 2)
  meldung.push("Die Rechnung fuehrt nur " + rgSkus.length + " Warenposition - die Mindestschwelle von 2 Treffern ist damit nicht erreichbar.");
if (protokoll.length)
  meldung.push("Geprueft: " + protokoll.join(" \u00b7 "));
else
  meldung.push("Fuer diesen Store existiert keine gueltige Bestandspruefung.");
if (positionenAmLimit)
  meldung.push("Positionsliste am Seitenlimit (" + SEITENGROESSE + ") - moeglicherweise fehlen Zeilen, Filter in Modul 112 pruefen.");

return raus("unklar", meldung.join("\n"));
